// Generated by Viscosity: "blocks" stored as AoSoA, blocks of 4 (fields x, y).
class __Vsc_blocks {
  constructor(cap = 8) { this.length = 0; this.cap = Math.ceil(cap / 4) * 4; this.data = new Float64Array(this.cap * 2); }
  static of(...v) { const c = new __Vsc_blocks(v.length / 2); for (let i = 0; i < v.length; i += 2) c.push(v[i + 0], v[i + 1]); return c; }
  push(v0, v1) { const n = this.length; if (n === this.cap) this.grow(); const b = (n >> 2) * 8 + (n & 3); this.data[b + 0] = v0; this.data[b + 4] = v1; return (this.length = n + 1); }
  grow() { const d = new Float64Array(this.cap * 2 * 2); d.set(this.data); this.data = d; this.cap *= 2; }
}
// Generated by Viscosity: "small" stored as a struct of arrays (fields v).
class __Vsc_small {
  constructor(cap = 16) { this.length = 0; this.cap = cap; this.v = new Float64Array(cap); }
  static of(...v) { const c = new __Vsc_small(Math.max(16, v.length / 1)); for (let i = 0; i < v.length; i += 1) c.push(v[i + 0]); return c; }
  push(v0) { const n = this.length; if (n === this.cap) this.grow(); this.v[n] = v0; return (this.length = n + 1); }
  grow() { const cap = (this.cap *= 2); let t; t = new Float64Array(cap); t.set(this.v); this.v = t; }
}
/* @viscosity aosoa(4) */
const blocks = new __Vsc_blocks();
// @viscosity aos
const plain = [];
const small = new __Vsc_small(); // @viscosity soa
// @viscosity aosoa(4)
const mixed = [];
for (let i = 0; i < 300; i++) { blocks.push(i, 2 * i); plain.push({ x: i }); small.push(i); mixed.push({ n: i, s: 's' + i }); }
let t = 0;
for (let i = 0; i < blocks.length; i++) { blocks.data[((i) >> 2) * 8 + 0 + ((i) & 3)] += blocks.data[((i) >> 2) * 8 + 4 + ((i) & 3)]; t += plain[i].x + small.v[i] + mixed[i].n; }
console.log(t, blocks.data[((17) >> 2) * 8 + 0 + ((17) & 3)], blocks.data[((299) >> 2) * 8 + 4 + ((299) & 3)], small.v[0]);
